/** Large exports (recordings, a whole project) as a stored ZIP streamed while it is produced, or as a directory tree. */
import { constants } from 'node:fs';
import { copyFile, mkdir, open, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import { Readable } from 'node:stream';
import { crc32 } from 'node:zlib';

/** One file of an export: generated bytes, a file on disk copied as it is, or bytes produced while the archive is read
 * (their size is unknown until the end, so such an entry is always written with ZIP64 sizes). `changing` marks a file
 * someone may be writing (a live workspace): one that shrinks or vanishes is reported there and keeps what was read,
 * where any other file refuses the whole export. */
export type ExportEntry = { name: string; modified?: Date } & ({ data: Uint8Array } | { file: string; bytes: number; changing?: (problem: string) => void } | { stream: AsyncIterable<Uint8Array> });

const u16 = (value: number) => { const buffer = Buffer.alloc(2); buffer.writeUInt16LE(value); return buffer; };
const u32 = (value: number) => { const buffer = Buffer.alloc(4); buffer.writeUInt32LE(value >>> 0); return buffer; };
const u64 = (value: number) => { const buffer = Buffer.alloc(8); buffer.writeBigUInt64LE(BigInt(value)); return buffer; };
const LIMIT = 0xffffffff;
function dosTime(date: Date): [number, number] {
  const year = Math.min(2107, Math.max(1980, date.getFullYear()));
  return [(date.getHours() << 11) | (date.getMinutes() << 5) | Math.floor(date.getSeconds() / 2), ((year - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate()];
}
async function* fileChunks(path: string, bytes: number): AsyncGenerator<Buffer> {
  if (bytes <= 0) return;
  const handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  try { for await (const chunk of handle.createReadStream({ end: bytes - 1, autoClose: false }) as AsyncIterable<Buffer>) yield chunk; }
  finally { await handle.close(); }
}

/** The bytes of one entry in pieces of at most 1 MiB, so a large generated value does not sit in the stream's queue
 * as one chunk. */
async function* entryChunks(entry: ExportEntry): AsyncGenerator<Buffer> {
  const sliced = function* (bytes: Uint8Array) { for (let at = 0; at < bytes.byteLength; at += SLICE) yield Buffer.from(bytes.buffer, bytes.byteOffset + at, Math.min(SLICE, bytes.byteLength - at)); };
  if ('data' in entry) yield* sliced(entry.data);
  else if ('file' in entry) yield* fileChunks(entry.file, entry.bytes);
  else for await (const chunk of entry.stream) yield* sliced(chunk);
}
const SLICE = 1024 * 1024;
const aborted = (signal?: AbortSignal) => signal?.aborted === true;

/** A stored (uncompressed: PNG, MP4 and CAD files are compressed already) ZIP with data descriptors, and ZIP64
 * records where sizes, offsets or the entry count pass the classic limits, or where the size is not known in advance.
 *
 * With `signal` (the HTTP request's: the client went away), the archive stops between two pieces and ends quietly: no
 * further entry is produced, open files are closed, and the producer's own cleanup runs. The HTTP bridge keeps reading
 * a response after a disconnect, so without this a multi-gigabyte export would be read to its end for nobody. */
export function zipStream(entries: AsyncIterable<ExportEntry>, signal?: AbortSignal): ReadableStream<Uint8Array> {
  async function* archive(): AsyncGenerator<Buffer> {
    const central: Buffer[] = []; let offset = 0, count = 0;
    try {
      for await (const entry of entries) {
        if (aborted(signal)) return;
        const streamed = 'stream' in entry, size = 'data' in entry ? entry.data.byteLength : 'file' in entry ? entry.bytes : 0;
        const name = Buffer.from(entry.name, 'utf8'), large = streamed || size >= LIMIT, [time, date] = dosTime(entry.modified ?? new Date()), at = offset;
        // CRC and sizes follow the data in the descriptor (64-bit for large or unsized entries, announced by a ZIP64 extra
        // field with zero sizes); readers take them from the central directory.
        const localExtra = large ? Buffer.concat([u16(1), u16(16), u64(0), u64(0)]) : Buffer.alloc(0);
        const local = Buffer.concat([u32(0x04034b50), u16(large ? 45 : 20), u16(0x0808), u16(0), u16(time), u16(date), u32(0), u32(0), u32(0), u16(name.length), u16(localExtra.length), name, localExtra]);
        yield local; offset += local.length;
        let checksum = 0, read = 0;
        const changing = 'file' in entry ? entry.changing : undefined;
        try {
          for await (const chunk of entryChunks(entry)) {
            if (aborted(signal)) return;
            checksum = crc32(chunk, checksum); read += chunk.length; yield chunk;
          }
        } catch (error) {
          if (!changing || aborted(signal)) throw error;
          changing(`${entry.name}：读取时出错（${error instanceof Error ? error.message : String(error)}）`);
        }
        if (!streamed && read !== size) {
          if (!changing) throw new Error(`导出文件在打包时发生变化：${entry.name}`);
          if (read) changing(`${entry.name}：打包时文件变小了，只有前 ${read} 字节`);
        }
        offset += read;
        const descriptor = Buffer.concat([u32(0x08074b50), u32(checksum), ...(large ? [u64(read), u64(read)] : [u32(read), u32(read)])]);
        yield descriptor; offset += descriptor.length;
        const far = at >= LIMIT, extra = large || far ? Buffer.concat([u16(1), u16((large ? 16 : 0) + (far ? 8 : 0)), ...(large ? [u64(read), u64(read)] : []), ...(far ? [u64(at)] : [])]) : Buffer.alloc(0);
        central.push(Buffer.concat([u32(0x02014b50), u16(0x0300 | 45), u16(large || far ? 45 : 20), u16(0x0808), u16(0), u16(time), u16(date), u32(checksum),
          u32(large ? LIMIT : read), u32(large ? LIMIT : read), u16(name.length), u16(extra.length), u16(0), u16(0), u16(0), u32((0o100644 << 16) >>> 0), u32(far ? LIMIT : at), name, extra]));
        count++;
      }
    } catch (error) {
      // The producer noticed the same cancellation first (throwIfAborted): still a quiet end.
      if (aborted(signal)) return;
      throw error;
    }
    if (aborted(signal)) return;
    const start = offset, directoryBytes = central.reduce((sum, entry) => sum + entry.length, 0);
    for (const entry of central) yield entry;
    offset += directoryBytes;
    const zip64 = count >= 0xffff || start >= LIMIT || directoryBytes >= LIMIT;
    if (zip64) {
      yield Buffer.concat([u32(0x06064b50), u64(44), u16(0x0300 | 45), u16(45), u32(0), u32(0), u64(count), u64(count), u64(directoryBytes), u64(start)]);
      yield Buffer.concat([u32(0x07064b50), u32(0), u64(offset), u32(1)]);
    }
    yield Buffer.concat([u32(0x06054b50), u16(0), u16(0), u16(zip64 ? 0xffff : count), u16(zip64 ? 0xffff : count), u32(zip64 ? LIMIT : directoryBytes), u32(zip64 ? LIMIT : start), u16(0)]);
  }
  return Readable.toWeb(Readable.from(archive())) as ReadableStream<Uint8Array>;
}

/** Writes the entries under a new directory (refused when it exists). Returns the totals. */
export async function writeTree(entries: AsyncIterable<ExportEntry>, directory: string, onProgress?: (files: number, bytes: number) => void): Promise<{ files: number; bytes: number }> {
  const root = resolve(directory); await mkdir(dirname(root), { recursive: true, mode: 0o755 }); await mkdir(root, { mode: 0o755 });
  let files = 0, bytes = 0;
  for await (const entry of entries) {
    const target = resolve(join(root, ...entry.name.split('/')));
    if (!target.startsWith(root + sep)) throw new Error(`导出路径无效：${entry.name}`);
    await mkdir(dirname(target), { recursive: true, mode: 0o755 });
    if ('data' in entry) { await writeFile(target, entry.data, { flag: 'wx', mode: 0o644 }); bytes += entry.data.byteLength; }
    else if ('file' in entry) {
      try { await copyFile(entry.file, target, constants.COPYFILE_EXCL); bytes += entry.bytes; }
      catch (error) { if (!entry.changing) throw error; entry.changing(`${entry.name}：读取时出错（${error instanceof Error ? error.message : String(error)}）`); continue; }
    }
    else {
      const handle = await open(target, 'wx', 0o644);
      try { for await (const chunk of entry.stream) { await handle.write(chunk); bytes += chunk.byteLength; } } finally { await handle.close(); }
    }
    files++; onProgress?.(files, bytes);
  }
  return { files, bytes };
}
